# Analyze demo vs test inputs for the "objects stack until touching" idea and check shapes.
I=G['Demo pair 1 input']; O=G['Demo pair 1 output']; T=G['Test input']
def objs(g):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                col=g[i][j]; st=[(i,j)]; cells=[]
                seen[i][j]=True
                while st:
                    r,c=st.pop(); cells.append((r,c))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            nr,nc=r+dr,c+dc
                            if 0<=nr<H and 0<=nc<W and not seen[nr][nc] and g[nr][nc]==col:
                                seen[nr][nc]=True; st.append((nr,nc))
                out.append((col,cells))
    return out
print("demo in:",[(c,(min(r for r,_ in cs),max(r for r,_ in cs),min(c for _,c in cs),max(c for _,c in cs))) for c,cs in objs(I)])
print("demo out:",[(c,(min(r for r,_ in cs),max(r for r,_ in cs),min(c for _,c in cs),max(c for _,c in cs))) for c,cs in objs(O)])
print("test in :",[(c,(min(r for r,_ in cs),max(r for r,_ in cs),min(c for _,c in cs),max(c for _,c in cs))) for c,cs in objs(T)])

